_N = [
("def","definition","critère",2,0,EXP+" ; "+CB+" ; "+SC,"Une paresthésie canalaire naît de la compression focale d'un nerf dans un passage étroit : le nerf médian au canal carpien, le nerf ulnaire au coude et le nerf cutané latéral de la cuisse sous le ligament inguinal."),
("epi","epidemiology","chiffre",1,0,CO+" ; "+SC,"Le syndrome du canal carpien est la compression nerveuse la plus fréquente, la neuropathie ulnaire au coude vient en deuxième ; la méralgie paresthésique touche environ 32 personnes sur 100 000 par an."),
("mech","basicSciences","mécanisme",1,0,AA,"La pression élevée dans le canal comprime le nerf ; une compression longue et non traitée entraîne une perte sensitive et motrice définitive."),
("rf","anamnesis","terrain particulier",2,0,WP+" ; "+HS+" ; "+AA,"Un IMC > 25 kg/m², le sexe féminin, le diabète, la grossesse, l'hypothyroïdie, l'arthrite et l'amylose favorisent le canal carpien ; l'AAOS ne retient pas d'association avec le travail au clavier (consensus)."),
("noct","anamnesis","symptôme",3,0,WP,"Le canal carpien donne des paresthésies et des douleurs du pouce, de l'index, du majeur et de la moitié radiale de l'annulaire, qui réveillent la nuit et cèdent quand le patient change la position de la main."),
("ulnsym","anamnesis","symptôme",2,0,CB+" ; "+EXP,"La compression ulnaire au coude donne des paresthésies du 5e doigt et de la moitié ulnaire du 4e, que la flexion prolongée du coude aggrave."),
("mpsym","anamnesis","symptôme",2,0,SC+" ; "+EXP,"La méralgie paresthésique donne une brûlure et une hypoesthésie de la face antéro-latérale de la cuisse, sans déficit moteur, car le nerf cutané latéral est purement sensitif."),
("tests","clinicalExam","signe",2,0,WP,"Les signes de Phalen (sensibilité 57 %, spécificité 67 %) et de Tinel (sensibilité 45 %) ont une valeur modeste : un test négatif n'exclut pas le diagnostic."),
("ulnexam","clinicalExam","signe",1,0,EXP,"Au coude, l'atteinte ulnaire touche les interosseux (signe de Froment) et la sensibilité du dos de la main côté ulnaire, que respecte une compression au canal de Guyon."),
("atroph","presumptionRedFlags","signe",3,0,WP,"L'amyotrophie thénarienne, la faiblesse de l'abduction ou de l'opposition du pouce et une perte sensitive permanente signent une forme sévère qu'on adresse au chirurgien."),
("rad","presumptionRedFlags","diagnostic différentiel",2,0,WP,"Une douleur cervicale, une hypoesthésie limitée au pouce et à l'index et un signe de Spurling positif orientent vers une radiculopathie C6–C7."),
("mpred","presumptionRedFlags","piège",1,0,EXP,"Une atteinte de la cuisse avec faiblesse du quadriceps ou réflexe rotulien aboli n'est pas une méralgie : on cherche une atteinte du nerf fémoral ou une radiculopathie L3–L4, par exemple un hématome rétropéritonéal sous anticoagulant."),
("cts6","workupGoldStandard","critère",3,0,AA+" ; "+WP,"Le score CTS-6 suffit au diagnostic du canal carpien (recommandation forte AAOS 2024) : un score ≥ 12 donne une probabilité d'environ 80 % ; l'échographie et l'ENMG ne sont pas systématiques."),
("emg","workupGoldStandard","examen",2,0,WP+" ; "+AA,"On réserve l'ENMG aux présentations atypiques, au diagnostic différentiel et à l'évaluation de la sévérité ; il reste normal chez 15 à 25 % des patients, donc un ENMG normal n'exclut pas le diagnostic."),
("ulnemg","workupGoldStandard","examen",1,0,CB,"L'ENMG et l'échographie confirment la neuropathie ulnaire au coude."),
("us","workupAlternatives","examen",1,0,AA,"L'échographie du nerf médian sert quand le score CTS-6 laisse un doute ; l'IRM ne sert pas au diagnostic (recommandation modérée AAOS 2024)."),
("mpdx","positiveDiagnosis","critère",1,0,SC,"Le diagnostic de méralgie repose sur les symptômes typiques et la réponse à une infiltration ; l'ENMG, la neurosonographie et l'IRM servent dans les cas atypiques."),
("lab","positiveDiagnosis","examen",1,0,EXP+" ; "+AA,"Un canal carpien bilatéral sans cause évidente fait chercher un diabète ou une hypothyroïdie ; si plusieurs facteurs de risque d'amylose existent, on peut analyser la ténosynoviale lors de la libération (consensus AAOS)."),
("splint","acuteManagement","décision",3,0,WP,"Une attelle de poignet en position neutre, portée la nuit au moins 1 à 2 mois, traite en première intention les formes légères à modérées ; le port nocturne vaut le port continu."),
("inj","acuteManagement","posologie",2,0,WP+" ; "+AA,"Une infiltration de corticostéroïde soulage jusqu'à 6 mois, mais n'apporte pas d'amélioration durable (recommandation forte AAOS 2024) ; la dose (par ex. méthylprednisolone 40 mg) est à vérifier dans l'AIPS (Swissmedic)."),
("noeff","acuteManagement","piège",2,0,AA+" ; "+WP,"Les AINS oraux, les diurétiques, les anticonvulsivants oraux, le PRP et les ultrasons thérapeutiques ne font pas mieux qu'un placebo ou n'apportent rien à long terme."),
("ulncons","acuteManagement","décision",1,0,CB+" ; "+CO,"Pour une neuropathie ulnaire légère, on informe le patient, on évite la flexion prolongée et l'appui sur le coude, et on peut proposer une attelle nocturne."),
("surg","chronicManagement","décision",2,0,AA+" ; "+WP,"La libération du canal carpien soulage 70 à 90 % des patients ; la technique ouverte et l'endoscopique se valent, et l'anesthésie locale seule suffit (recommandations fortes AAOS 2024)."),
("ulnsurg","chronicManagement","décision",1,0,CO,"Au coude, la décompression simple donne des résultats comparables à la transposition antérieure, même pour une atteinte sévère."),
("mptx","chronicManagement","décision",1,0,SC+" ; "+EXP,"Pour la méralgie, on retire la compression (ceinture serrée, perte de poids), puis on discute une infiltration ; la décompression ou la neurectomie traitent les formes rebelles."),
("postop","hospitalizationComplications","complication",1,0,AA+" ; "+WP,"Autour de la libération, on renonce aux examens préopératoires de routine, à l'antibioprophylaxie et à l'attelle postopératoire ; l'anticoagulant peut souvent être poursuivi ; les complications graves restent < 2 %."),
("surv","surveillance","examen",1,0,WP+" ; "+EXP,"On réévalue le patient après 1 à 2 mois d'attelle et on adresse au chirurgien en cas d'échec ou de déficit objectif."),
("prono","prognosisDischarge","pronostic",1,0,EXP,"Un canal carpien de la grossesse régresse souvent après l'accouchement ; un déficit installé récupère moins bien qu'une gêne sensitive."),
("net","followUpNetwork","contexte suisse",1,1,EXP,"Le médecin de famille, le neurologue (ENMG) et le chirurgien de la main collaborent ; en Suisse, une origine professionnelle se discute avec l'assureur-accidents selon la LAA (à vérifier sur fedlex.admin.ch)."),
]
